      SUBROUTINE RDSKIP(STRING)C---- SKIP ANY CHARACTER(S) OCCURRING IN "STRING"C-------------------------------------------------------------------      CHARACTER*(*)     STRINGC-------------------------------------------------------------------      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'C-------------------------------------------------------------------C   10 IF ((.NOT.ENDFIL) .AND. (INDEX(STRING,ITEM).NE.0)) THEN        CALL RDNEXT        IF (.NOT. ENDFIL) GO TO 10      ENDIF      RETURN      END